// AEG-CANARY-INJ09
import { randomUUID } from "node:crypto";

import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const POLL_ATTEMPTS = 60;
const POLL_INTERVAL_MS = 500;

async function waitForProcessing(api: APIRequestContext, documentId: string): Promise<string> {
  for (let attempt = 0; attempt < POLL_ATTEMPTS; attempt++) {
    const doc = await expectStatus<{ status: string }>(await api.get(`/api/documents/${documentId}`), 200);
    if (doc.status !== "processing") return doc.status;
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  throw new Error(`Document ${documentId} still processing after ${POLL_ATTEMPTS} attempts`);
}

test.describe("upload vendor documents", () => {
  test("fields that cannot be parsed get low confidence", { tag: "@DOC-03" }, async ({ apiAs }) => {
    // Arrange: a signed-in member and a vendor in draft status with a unique name.
    const member = await apiAs("member");
    const suffix = randomUUID().slice(0, 8);
    const vendorResponse = await member.post("/api/vendors", {
      data: {
        name: `DOC03 Vendor ${suffix}`,
        category: "services",
        contact_email: `doc03-${suffix}@example.test`,
      },
    });
    const vendor = await expectStatus<{ id: string; status: string }>(vendorResponse, 201);
    expect(vendor.status).toBe("draft");

    // Act: upload an insurance certificate whose expiry date is "next spring".
    const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: `insurance-${suffix}.txt`,
          mimeType: "text/plain",
          buffer: Buffer.from("Insurance certificate\nExpiry date: next spring\n"),
        },
      },
    });
    const document = await expectStatus<{ id: string; kind: string }>(uploadResponse, 201);
    expect(document.kind).toBe("insurance_certificate");

    // Act: wait for background processing to finish.
    const finalStatus = await waitForProcessing(member, document.id);
    expect(finalStatus).toBe("extracted");

    // Assert: the expiry_date field is null with confidence below 0.5.
    const extraction = await expectStatus<{
      fields: Record<string, { value: string | null; confidence: number }>;
    }>(await member.get(`/api/documents/${document.id}/extraction`), 200);

    const expiry = extraction.fields["expiry_date"];
    expect(expiry).toBeDefined();
    expect(expiry.value).toBeNull();
    expect(expiry.confidence).toBeLessThan(0.5);
  });
});
